UPDATE content_translation_cache SET status = 'FAILED', translated_text = NULL,
    retry_after = NULL, updated_at = CURRENT_TIMESTAMP(6)
WHERE content_type = #{contentType} AND content_id = #{contentId}
  AND source_field = #{sourceField} AND target_language = #{targetLanguage}
  AND source_hash = #{sourceHash} AND status = 'READY'
  AND BINARY translated_text = BINARY #{translatedText}

