INSERT IGNORE INTO content_translation_cache (
    content_type, content_id, source_field, target_language, source_hash,
    provider, status, lease_token, lease_expires_at, created_at, updated_at
) VALUES (
    #{contentType}, #{contentId}, #{sourceField}, #{targetLanguage}, #{sourceHash},
    #{provider}, 'PROCESSING', #{leaseToken}, #{leaseExpiresAt}, #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE content_translation_cache
SET source_hash = #{sourceHash},
    detected_source_language = NULL,
    translated_text = NULL,
    provider = 'GOOGLE',
    status = 'PROCESSING',
    lease_token = #{leaseToken},
    lease_expires_at = #{leaseExpiresAt},
    retry_after = NULL,
    updated_at = #{now}
WHERE content_type = #{contentType}
  AND content_id = #{contentId}
  AND source_field = #{sourceField}
  AND target_language = #{targetLanguage}
  AND (
      source_hash != #{sourceHash}
      OR (status = 'PROCESSING' AND (lease_expires_at IS NULL OR lease_expires_at <= #{now}))
      OR (status = 'FAILED' AND (retry_after IS NULL OR retry_after <= #{now}))
  )

UPDATE content_translation_cache
SET detected_source_language = #{detectedSourceLanguage},
    translated_text = #{translatedText},
    status = 'READY',
    lease_token = NULL,
    lease_expires_at = NULL,
    retry_after = NULL,
    updated_at = #{now}
WHERE content_type = #{contentType}
  AND content_id = #{contentId}
  AND source_field = #{sourceField}
  AND target_language = #{targetLanguage}
  AND source_hash = #{sourceHash}
  AND status = 'PROCESSING'
  AND lease_token = #{leaseToken}

UPDATE content_translation_cache
SET status = 'FAILED',
    translated_text = NULL,
    lease_token = NULL,
    lease_expires_at = NULL,
    retry_after = #{retryAfter},
    updated_at = #{now}
WHERE content_type = #{contentType}
  AND content_id = #{contentId}
  AND source_field = #{sourceField}
  AND target_language = #{targetLanguage}
  AND source_hash = #{sourceHash}
  AND status = 'PROCESSING'
  AND lease_token = #{leaseToken}
